static void seed(void)
{
	srand(time(NULL) ^ getpid());
}

static const char *one_of(const char **lines, int n)
{
	return lines[rand() % n];
}
#define ONE_OF(...) one_of((const char *[]){ __VA_ARGS__ }, \
	sizeof((const char *[]){ __VA_ARGS__ }) / sizeof(const char *))

static int fdiv(int a, int b)
{
	return a / b - (a % b < 0);
}

static int nyan_star(int x, int y, int f)
{
	x += 2 * f;
	int gx = fdiv(x, 12), gy = fdiv(y, 8);
	unsigned hash = (unsigned)(gx * 73856093) ^ (unsigned)(gy * 19349663);
	if (hash % 2)
		return 0;
	int dx = x - (gx * 12 + (int)(hash / 2 % 12)), dy = y - (gy * 8 + (int)(hash / 24 % 8));
	if (dx == 0 && dy == 0)
		return 1;
	return (f / 3 + hash) % 3 == 1 && (dx < 0 ? -dx : dx) + (dy < 0 ? -dy : dy) == 1;
}

static char nyan_pixel(const char **fr, int x, int y, int f)
{
	char c = ',';
	if (y >= 0 && y < 64 && x < 64) {
		c = x >= 0 ? fr[y][x] : fr[y][((x % 16) + 16) % 16];
		if (x < 0 && !strchr("><&+#=;", c))
			c = ',';
	}
	return c == ',' && nyan_star(x, y, f) ? '.' : c;
}

static void nyan(void)
{
	static int color[128];
	seed();
	const char *title = ONE_OF("minish: now with 100% more pop-tart", "nyan > /dev/stdout",
		"segfault-free since the last commit");
	const char *hint = "press CTRL + C to go back";
	time_t start = time(NULL);

	color[','] = 17;  color['.'] = 231; color['\''] = 16; color['@'] = 230;
	color['$'] = 175; color['-'] = 162; color['>'] = 196;  color['&'] = 214;
	color['+'] = 226; color['#'] = 118; color['='] = 33;   color[';'] = 19;
	color['*'] = 240; color['%'] = 175;

	write(STDOUT_FILENO, "\x1b[?1049h\x1b[?25l", 14);

	for (int f = 0;; f++) {
		struct winsize ws;
		int w = 80, h = 24;
		if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
			w = ws.ws_col;
			h = ws.ws_row;
		}

		const char **fr = nyan_frames[f % 12];
		char *buf = malloc((size_t)w * h * 32 + 64);
		if (!buf)
			_exit(1);
		char counter[64];
		snprintf(counter, sizeof(counter), "You have nyaned for %ld seconds!", (long)(time(NULL) - start));
		int n = 0, lfg = -1, lbg = -1;
		int px0 = 34 - w / 2, py0 = 32 - h;

		for (int y = 0; y < h; y++) {
			n += sprintf(buf + n, "\x1b[%d;1H", y + 1);
			const char *text = y == 0 ? title : y == h - 2 ? counter : y == h - 1 ? hint : NULL;
			int tx = text ? (w - (int)strlen(text)) / 2 : 0;

			for (int x = 0; x < w; x++) {
				int fg, bg;
				char c = 0;
				if (text && x >= tx && x < tx + (int)strlen(text)) {
					c = text[x - tx];
					fg = y == h - 1 ? 250 : 231;
					bg = 17;
				} else {
					fg = color[(unsigned char)nyan_pixel(fr, px0 + x, py0 + 2 * y, f)];
					bg = color[(unsigned char)nyan_pixel(fr, px0 + x, py0 + 2 * y + 1, f)];
				}
				if (fg != lfg || bg != lbg) {
					n += sprintf(buf + n, "\x1b[38;5;%d;48;5;%dm", fg, bg);
					lfg = fg;
					lbg = bg;
				}
				if (c)
					buf[n++] = c;
				else
					n += sprintf(buf + n, "\u2580");
			}
		}

		write(STDOUT_FILENO, buf, n);
		free(buf);
		nanosleep(&(struct timespec){ .tv_nsec = 90000000 }, NULL);
	}
}

#define MAXW 512
#define MAXH 256

struct canvas {
	int w, h;
	char *ch;
	unsigned char *fg, *bg;
};

static void canvas_open(struct canvas *cv)
{
	struct winsize ws;
	cv->w = 80;
	cv->h = 24;
	if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
		cv->w = ws.ws_col;
		cv->h = ws.ws_row;
	}
	if (cv->w > MAXW)
		cv->w = MAXW;
	if (cv->h > MAXH)
		cv->h = MAXH;
	size_t n = (size_t)cv->w * cv->h;
	cv->ch = malloc(n);
	cv->fg = malloc(n);
	cv->bg = malloc(n);
	if (!cv->ch || !cv->fg || !cv->bg)
		_exit(1);
	memset(cv->ch, ' ', n);
	memset(cv->fg, 255, n);
	memset(cv->bg, 16, n);
}

static void canvas_put(struct canvas *cv, int x, int y, const char *s, int fg, int bg)
{
	for (; *s && x < cv->w; s++, x++) {
		if (x < 0 || y < 0 || y >= cv->h || *s == ' ')
			continue;
		int i = y * cv->w + x;
		cv->ch[i] = *s;
		cv->fg[i] = fg;
		if (bg >= 0)
			cv->bg[i] = bg;
	}
}

static void canvas_set(struct canvas *cv, int x, int y, char c, int fg)
{
	if (x >= 0 && y >= 0 && x < cv->w && y < cv->h) {
		cv->ch[y * cv->w + x] = c;
		cv->fg[y * cv->w + x] = fg;
	}
}

static void canvas_fill(struct canvas *cv, int x0, int y0, int w, int h, int bg)
{
	for (int y = y0; y < y0 + h; y++)
		for (int x = x0; x < x0 + w; x++)
			if (x >= 0 && y >= 0 && x < cv->w && y < cv->h) {
				cv->ch[y * cv->w + x] = ' ';
				cv->bg[y * cv->w + x] = bg;
			}
}

static void canvas_center(struct canvas *cv, int x, int y, const char *s, int fg, int bg)
{
	canvas_put(cv, x - (int)strlen(s) / 2, y, s, fg, bg);
}

static void canvas_flush(struct canvas *cv)
{
	char *buf = malloc((size_t)cv->w * cv->h * 24 + 64);
	if (!buf)
		_exit(1);
	int n = 0, lfg = -1, lbg = -1;

	for (int y = 0; y < cv->h; y++) {
		n += sprintf(buf + n, "\x1b[%d;1H", y + 1);
		for (int x = 0; x < cv->w; x++) {
			int i = y * cv->w + x;
			if (cv->fg[i] != lfg || cv->bg[i] != lbg) {
				lfg = cv->fg[i];
				lbg = cv->bg[i];
				n += sprintf(buf + n, "\x1b[38;5;%d;48;5;%dm", lfg, lbg);
			}
			buf[n++] = cv->ch[i];
		}
	}

	write(STDOUT_FILENO, buf, n);
	free(buf);
	free(cv->ch);
	free(cv->fg);
	free(cv->bg);
}

static void forkbomb(void)
{
	static const char *big[3] = { " /\\_/\\ ", "( o.o )", " > ^ < " };
	static const int colors[] = { 255, 218, 213, 177, 141, 111, 81, 86, 120, 192, 228, 222, 215, 209 };
	const int ncolors = sizeof(colors) / sizeof(colors[0]);
	const int hold = 8, split = 6;
	int gen = 0, step = 0, crash = 0;
	unsigned rnd = 12345;

	seed();
	write(STDOUT_FILENO, "\x1b[?1049h\x1b[?25l", 14);

	for (;;) {
		struct canvas cv;
		canvas_open(&cv);
		int top = 2, ah = cv.h - 5;
		char line[64];

		if (crash) {
			for (int i = 0; i < cv.w * cv.h; i++) {
				rnd = rnd * 1103515245 + 12345;
				cv.ch[i] = "@=^.^="[(rnd >> 16) % 6];
				cv.fg[i] = colors[(rnd >> 8) % ncolors];
			}
			for (int y = cv.h / 2 - 1; y <= cv.h / 2 + 1; y++)
				for (int x = cv.w / 2 - 22; x <= cv.w / 2 + 22; x++)
					if (x >= 0 && x < cv.w) {
						cv.ch[y * cv.w + x] = ' ';
						cv.bg[y * cv.w + x] = 52;
					}
			canvas_center(&cv, cv.w / 2, cv.h / 2, "fork: Resource temporarily unavailable", 255, 52);
			canvas_fill(&cv, cv.w / 2 - 20, cv.h / 2 + 3, 40, 1, 16);
			canvas_center(&cv, cv.w / 2, cv.h / 2 + 3, "this is why we can't have nice things", 250, -1);
			if (++crash > 25)
				crash = gen = step = 0;
		} else {
			int splitting = step >= hold;
			int next = gen + splitting;
			int cols = 1 << ((next + 1) / 2), rows = 1 << (next / 2);
			int cw = cv.w / cols, ch = ah / rows;
			int tier = (cw >= 8 && ch >= 4) ? 0 : (cw >= 6 && ch >= 1) ? 1 : (cw >= 2 && ch >= 1) ? 2 : -1;

			if (tier < 0) {
				crash = 1;
				free(cv.ch);
				free(cv.fg);
				free(cv.bg);
				continue;
			}

			float t = splitting ? (float)(step - hold + 1) / split : 1;
			int wide = (next & 1);

			for (int j = 0; j < rows; j++) {
				for (int i = 0; i < cols; i++) {
					float x1 = (i + 0.5f) * cv.w / cols, y1 = top + (j + 0.5f) * ah / rows;
					float x0 = x1, y0 = y1;
					int child = wide ? (i & 1) : (j & 1);
					if (splitting) {
						int pcols = wide ? cols / 2 : cols, prows = wide ? rows : rows / 2;
						x0 = ((wide ? i / 2 : i) + 0.5f) * cv.w / pcols;
						y0 = top + ((wide ? j : j / 2) + 0.5f) * ah / prows;
					}
					int x = x0 + (x1 - x0) * t, y = y0 + (y1 - y0) * t;
					int fg = colors[(splitting && child ? next : gen) % ncolors];

					if (tier == 0)
						for (int r = 0; r < 3; r++)
							canvas_center(&cv, x, y - 1 + r, big[r], fg, -1);
					else
						canvas_center(&cv, x, y, tier == 1 ? "=^.^=" : "@", fg, -1);
				}
			}

			if (++step >= hold + split) {
				step = 0;
				gen++;
			}
		}

		for (int x = 0; x < cv.w; x++)
			cv.ch[x] = cv.ch[(cv.h - 2) * cv.w + x] = cv.ch[(cv.h - 1) * cv.w + x] = ' ';
		canvas_center(&cv, cv.w / 2, 0, ":(){ :|:& };: please do not try this at home", 245, -1);
		snprintf(line, sizeof(line), "generation %d - %ld processes%s", gen, 1L << gen,
			gen >= 6 ? " - ulimit is getting nervous" : "");
		canvas_center(&cv, cv.w / 2, cv.h - 2, line, 255, -1);
		canvas_center(&cv, cv.w / 2, cv.h - 1, "press CTRL + C to go back", 240, -1);
		canvas_flush(&cv);
		nanosleep(&(struct timespec){ .tv_nsec = 100000000 }, NULL);
	}
}

#pragma region Shared

static const char *banner[5] = {
	"           _       _     _     ",
	" _ __ ___ (_)_ __ (_)___| |__  ",
	"| '_ ` _ \\| | '_ \\| / __| '_ \\ ",
	"| | | | | | | | | | \\__ \\ | | |",
	"|_| |_| |_|_|_| |_|_|___/_| |_|",
};
#define BANNER_W 31

static const int spectrum[] = {
	196, 202, 208, 214, 220, 226, 190, 154, 118, 82, 46, 47, 48, 49, 50,
	51, 45, 39, 33, 27, 21, 57, 93, 129, 165, 201, 200, 199, 198, 197,
};
#define NSPECTRUM (int)(sizeof(spectrum) / sizeof(spectrum[0]))

static void draw_banner(struct canvas *cv, int top, int fg, int f)
{
	int x0 = cv->w / 2 - BANNER_W / 2;
	for (int r = 0; r < 5; r++)
		for (int c = 0; c < BANNER_W; c++)
			if (banner[r][c] != ' ')
				canvas_set(cv, x0 + c, top + r, banner[r][c],
					fg >= 0 ? fg : spectrum[((x0 + c - f) % NSPECTRUM + NSPECTRUM) % NSPECTRUM]);
}

static void type_line(struct canvas *cv, int y, const char *s, int fg, int f, int start)
{
	char buf[128];
	int len = strlen(s), n = f - start;
	if (n < 0)
		return;
	if (n > len)
		n = len;
	if (len >= (int)sizeof(buf))
		len = n = sizeof(buf) - 1;
	memcpy(buf, s, n);
	buf[n] = '\0';
	canvas_put(cv, cv->w / 2 - len / 2, y, buf, fg, -1);
	if (n < len && (f & 2))
		canvas_set(cv, cv->w / 2 - len / 2 + n, y, '_', fg);
}

static void play(void (*draw)(struct canvas *cv, int f), int top)
{
	seed();
	write(STDOUT_FILENO, "\x1b[?1049h\x1b[?25l", 14);

	for (int f = 0;; f++) {
		struct canvas cv;
		canvas_open(&cv);
		draw(&cv, f);
		int y = top ? 0 : cv.h - 1;
		canvas_fill(&cv, cv.w / 2 - 14, y, 28, 1, 16);
		canvas_center(&cv, cv.w / 2, y, "press CTRL + C to go back", 240, -1);
		canvas_flush(&cv);
		nanosleep(&(struct timespec){ .tv_nsec = 100000000 }, NULL);
	}
}

