#pragma region "OS themed"

static void draw_pipe(struct canvas *cv, int f)
{
	static struct { int x, y, fg, state; } p[96];
	static const int other[] = { 196, 33, 226, 201 };
	static int counted, dropped;
	static const char *quip;
	const char *names[3] = { "ls", "grep txt", "wc -l" };
	int cy = cv->h / 2, bx[3], bw[3];
	char line[64];

	for (int i = 0; i < 3; i++) {
		bw[i] = strlen(names[i]) + 4;
		bx[i] = cv->w * (15 + 35 * i) / 100 - bw[i] / 2;
	}
	for (int i = 0; i < 3; i++) {
		for (int x = 0; x < bw[i]; x++) {
			char edge = (x == 0 || x == bw[i] - 1) ? '+' : '-';
			canvas_set(cv, bx[i] + x, cy - 1, edge, 250);
			canvas_set(cv, bx[i] + x, cy + 1, edge, 250);
		}
		snprintf(line, sizeof(line), "| %s |", names[i]);
		canvas_put(cv, bx[i], cy, line, 255, -1);
		if (i < 2) {
			for (int x = bx[i] + bw[i]; x < bx[i + 1]; x++)
				canvas_set(cv, x, cy, '=', 238);
			canvas_set(cv, bx[i + 1] - 1, cy, '>', 245);
		}
	}

	if (f % 2 == 0)
		for (int i = 0; i < 96; i++)
			if (p[i].state == 0) {
				p[i].x = bx[0] + bw[0];
				p[i].y = cy;
				p[i].fg = rand() % 5 < 2 ? 46 : other[rand() % 4];
				p[i].state = 1;
				break;
			}

	for (int i = 0; i < 96; i++) {
		if (p[i].state == 1) {
			p[i].x++;
			if (p[i].x >= bx[1] && p[i].x < bx[1] + bw[1]) {
				if (p[i].fg == 46) {
					p[i].x = bx[1] + bw[1];
				} else {
					p[i].state = 2;
					p[i].x = bx[1] + bw[1] / 2;
					p[i].y = cy + 2;
				}
			} else if (p[i].x >= bx[2]) {
				p[i].state = 0;
				counted++;
			}
		} else if (p[i].state == 2 && ++p[i].y >= cy + 5) {
			p[i].state = 0;
			dropped++;
		}
		if (p[i].state)
			canvas_set(cv, p[i].x, p[i].y, 'o', p[i].fg);
	}

	canvas_center(cv, cv->w / 2, 2, "ls | grep txt | wc -l", 255, -1);
	canvas_center(cv, bx[0] + bw[0] / 2, cy - 3, "*.c *.h *.txt", 245, -1);
	snprintf(line, sizeof(line), "%d", counted);
	canvas_center(cv, bx[2] + bw[2] / 2, cy - 3, line, 46, -1);
	snprintf(line, sizeof(line), "/dev/null (%d) - now accepting all applications", dropped);
	canvas_center(cv, bx[1] + bw[1] / 2, cy + 5, line, 240, -1);
	if (f == 0)
		quip = ONE_OF("grep: the bouncer of the pipeline", "data goes in, less data comes out",
			"every | is a pipe(): one process writes, the next one reads");
	canvas_center(cv, cv->w / 2, cv->h - 3, quip, 245, -1);
}

static void draw_zombie(struct canvas *cv, int f)
{
	static const char *zs[2][3] = {
		{ "(x_x)", "=--| ", " /  \\" },
		{ "(x_x)", "=--| ", "  || " },
	};
	static const char *reaper[4] = { "  .--.  ,_", " ( oo )  |", " /|  |\\--+", "  /__\\   |" };
	static float zx[4], zv[4], rx;
	static int alive[4], poof[4], reaped;
	static const char *quip;
	int ground = cv->h / 2 + 3;
	char line[32];

	if (f == 0 || rx > cv->w + 2) {
		for (int i = 0; i < 4; i++) {
			zx[i] = cv->w * (30 + 16 * i) / 100 + rand() % 3;
			zv[i] = 0.2f + (rand() % 5) / 100.0f;
			alive[i] = 1;
			poof[i] = 0;
		}
		rx = -12;
	}
	rx += 0.9f;

	for (int x = 0; x < cv->w; x++)
		canvas_set(cv, x, ground + 1, '_', 238);

	for (int i = 0; i < 4; i++) {
		if (alive[i]) {
			zx[i] -= zv[i];
			if (rx + 10 >= zx[i]) {
				alive[i] = 0;
				poof[i] = 20;
				reaped++;
				continue;
			}
			for (int r = 0; r < 3; r++)
				canvas_put(cv, zx[i], ground - 2 + r, zs[(f / 3 + i) & 1][r], 108, -1);
			canvas_center(cv, zx[i] + 2, ground - 3, "<defunct>", 240, -1);
		}
	}

	for (int r = 0; r < 4; r++)
		canvas_put(cv, rx, ground - 3 + r, reaper[r], 250, -1);
	canvas_center(cv, rx + 5, ground - 4, "SIGCHLD", 196, -1);

	for (int i = 0; i < 4; i++)
		if (poof[i] > 0) {
			canvas_center(cv, zx[i] + 2, ground - 5 - (20 - poof[i]) / 5, "*poof*", poof[i] > 6 ? 226 : 242, -1);
			poof[i]--;
		}

	snprintf(line, sizeof(line), "reaped: %d", reaped);
	canvas_put(cv, cv->w - (int)strlen(line) - 2, 1, line, 245, -1);
	if (f == 0)
		quip = ONE_OF("they're not dead, just <defunct>", "no zombies were harmed. they were reaped.",
			"a zombie is a child nobody waited for. waitpid() lets it rest.");
	canvas_center(cv, cv->w / 2, 2, "night of the living processes", 255, -1);
	canvas_center(cv, cv->w / 2, cv->h - 3, quip, 245, -1);
}

static void draw_tux(struct canvas *cv, int f)
{
	static const char *tux[7] = {
		"    .--.",
		"   |o_o |",
		"   |:_/ |",
		"  //   \\ \\",
		" (|     | )",
		"/'\\_   _/`\\",
		"\\___)=(___/",
	};
	static float fx[60], fy[60], tx = -12;
	static const char *quip;
	int ground = cv->h - 4;

	for (int i = 0; i < 60; i++) {
		if (f == 0) {
			fx[i] = rand() % cv->w;
			fy[i] = rand() % ground;
		}
		fy[i] += 0.25f + (i % 3) * 0.1f;
		fx[i] += ((f + i) / 8) & 1 ? 0.2f : -0.2f;
		if (fy[i] >= ground) {
			fy[i] = 0;
			fx[i] = rand() % cv->w;
		}
		canvas_set(cv, fx[i], fy[i], i % 2 ? '*' : '.', i % 2 ? 255 : 250);
	}
	for (int x = 0; x < cv->w; x++)
		canvas_set(cv, x, ground + 1, '~', 255);

	tx += 0.5f;
	if (tx > cv->w)
		tx = -12;
	int bob = (f / 2) & 1;

	for (int k = 0; k < 7 + bob; k++) {
		int r = bob && k >= 5 ? k - 1 : k;
		int y = ground - 6 - bob + k;
		int x = tx + (r == 6 ? bob : 0);
		int first = strspn(tux[r], " ");
		canvas_fill(cv, x + first, y, strlen(tux[r]) - first, 1, 16);
		for (int c = 0; tux[r][c]; c++) {
			char ch = tux[r][c];
			if (ch == ' ')
				continue;
			int fg = ch == 'o' ? 231 : (r == 2 && c >= 4 && c <= 6) || r == 6 ? 220 : 250;
			canvas_set(cv, x + c, y, ch, fg);
		}
	}

	if (f == 0)
		quip = ONE_OF("Tux approves of this shell", "waddling through the kernel since 1991",
			"sudo make me a sandwich");
	canvas_fill(cv, cv->w / 2 - (int)strlen(quip) / 2 - 1, 2, strlen(quip) + 2, 1, 16);
	canvas_center(cv, cv->w / 2, 2, quip, 255, -1);
}

