static void draw_matrix(struct canvas *cv, int f)
{
	static float head[MAXW], speed[MAXW];
	static int len[MAXW];
	static char glyph[MAXH][MAXW];
	static unsigned char shown[5][BANNER_W];
	static int done = -1;
	static const char *quip;
	static const int green[] = { 22, 28, 34, 40, 46 };
	const char *set = "abcdefghijklmnopqrstuvwxyz0123456789@#$%&*+=<>|/\\";
	int nset = strlen(set);
	int top = cv->h / 2 - 3, x0 = cv->w / 2 - BANNER_W / 2;

	if (f == 0)
		for (int y = 0; y < MAXH; y++)
			for (int x = 0; x < MAXW; x++)
				glyph[y][x] = set[rand() % nset];
	for (int i = 0; i < 40; i++)
		glyph[rand() % cv->h][rand() % cv->w] = set[rand() % nset];

	for (int x = 0; x < cv->w; x++) {
		if (f == 0 || head[x] - len[x] > cv->h) {
			head[x] = f == 0 ? -(rand() % cv->h) : -(rand() % 8);
			speed[x] = 0.3f + (rand() % 70) / 100.0f;
			len[x] = 4 + rand() % (cv->h / 2 + 1);
		}
		head[x] += speed[x];

		int hy = head[x];
		for (int y = hy - len[x]; y <= hy; y++)
			if (y >= 0 && y < cv->h)
				canvas_set(cv, x, y, glyph[y][x], y == hy ? 231 : green[(len[x] - (hy - y)) * 5 / (len[x] + 1)]);

		if (f > 20 && x >= x0 && x < x0 + BANNER_W && hy >= top && hy < top + 5)
			shown[hy - top][x - x0] = 1;
	}

	int all = 1;
	for (int r = 0; r < 5; r++)
		for (int c = 0; c < BANNER_W; c++) {
			if (!shown[r][c]) {
				all = 0;
				continue;
			}
			canvas_fill(cv, x0 + c, top + r, 1, 1, 16);
			canvas_set(cv, x0 + c, top + r, banner[r][c], 231);
		}

	if (all) {
		if (done < 0)
			done = f;
		if (f == done)
			quip = ONE_OF("there is no spoon. only fork().", "follow the white cursor");
		canvas_fill(cv, cv->w / 2 - 18, top + 6, 36, 3, 16);
		type_line(cv, top + 6, "wake up... the shell has you", 46, (f - done) / 2, 5);
		type_line(cv, top + 8, quip, 34, (f - done) / 2, 40);
	}
}

static void draw_warp(struct canvas *cv, int f)
{
	static float sx[200], sy[200], sz[200];
	int top = cv->h / 2 - 4;

	for (int i = 0; i < 200; i++) {
		if (f == 0 || sz[i] <= 0.05f) {
			sx[i] = (rand() % 2001 - 1000) / 1000.0f;
			sy[i] = (rand() % 2001 - 1000) / 1000.0f;
			sz[i] = f == 0 ? (rand() % 1000 + 1) / 1000.0f : 1;
		}
		sz[i] -= 0.015f + (f < 30 ? f : 30) * 0.0007f;

		int x = cv->w / 2 + sx[i] / sz[i] * cv->w / 4;
		int y = cv->h / 2 + sy[i] / sz[i] * cv->h / 4;
		if (x < 0 || y < 0 || x >= cv->w || y >= cv->h) {
			sz[i] = 0;
			continue;
		}
		char c = sz[i] > 0.6f ? '.' : sz[i] > 0.3f ? '+' : sz[i] > 0.15f ? '*' : '#';
		canvas_set(cv, x, y, c, 255 - (int)(sz[i] * 16));
	}

	int x0 = cv->w / 2 - BANNER_W / 2;
	for (int y = top - 1; y < top + 8; y++)
		for (int x = cv->w / 2 - 32; x < cv->w / 2 + 32; x++) {
			unsigned at = 30 + ((unsigned)(x * 73856093) ^ (unsigned)(y * 19349663)) % 30;
			if ((unsigned)f < at)
				continue;
			canvas_fill(cv, x, y, 1, 1, 16);
			int r = y - top, c = x - x0;
			if (r >= 0 && r < 5 && c >= 0 && c < BANNER_W && banner[r][c] != ' ')
				canvas_set(cv, x, y, banner[r][c], f - at < 19 ? 236 + f - at : 255);
		}
	static char home[96];
	static const char *quip;
	if (f == 0) {
		snprintf(home, sizeof(home), "to infinity and %s", getenv("HOME") ? getenv("HOME") : "/home");
		quip = ONE_OF("A tiny shell by Chatzikallias Panagiotis (ics24115)", home);
	}
	type_line(cv, top + 7, quip, 245, f, 70);
}

static void draw_fire(struct canvas *cv, int f)
{
	static unsigned char heat[MAXH + 1][MAXW];
	static const int colors[] = { 16, 52, 88, 124, 160, 196, 202, 208, 214, 220, 226, 228, 229, 230, 231 };
	const char *ramp = " .:-=+*#%@";
	int w = cv->w, h = cv->h;
	int cool = (int)(255 / (h * 0.55f)) + 1;

	for (int x = 0; x < w; x++)
		heat[h][x] = rand() % 6 ? 255 : 160;

	for (int y = 0; y < h; y++)
		for (int x = 0; x < w; x++) {
			int src = heat[y + 1][x], c = rand() % (2 * cool + 1);
			int dx = x + rand() % 3 - 1;
			if (dx < 0)
				dx = 0;
			if (dx >= w)
				dx = w - 1;
			heat[y][dx] = src > c ? src - c : 0;
		}

	for (int y = 0; y < h; y++)
		for (int x = 0; x < w; x++)
			if (heat[y][x] > 20)
				canvas_set(cv, x, y, ramp[heat[y][x] * 9 / 255], colors[heat[y][x] * 14 / 255]);

	draw_banner(cv, h / 5, 231, 0);
	static const char *quip;
	if (f == 0)
		quip = ONE_OF("(the build passed. the tests are another story)", "core dumped. warmly.");
	if (f > 15) {
		canvas_fill(cv, w / 2 - 8, h / 5 + 6, 16, 1, 16);
		canvas_center(cv, w / 2, h / 5 + 6, "this is fine.", 250, -1);
	}
	if (f > 40) {
		int len = strlen(quip);
		canvas_fill(cv, w / 2 - len / 2 - 1, h / 5 + 7, len + 2, 1, 16);
		canvas_center(cv, w / 2, h / 5 + 7, quip, 242, -1);
	}
}

static void draw_logo(struct canvas *cv, int f)
{
	const char *who = "hand-crafted by Chatzikallias Panagiotis (ics24115)";
	const char *what = "builtins - fork/exec - jobs - signals - redirects - pipes - cats";
	int top = cv->h / 2 - 5;

	draw_banner(cv, top, -1, f);
	type_line(cv, top + 7, who, 255, f, 10);
	type_line(cv, top + 9, what, 245, f, 15 + strlen(who));
}

static void draw_fedora(struct canvas *cv, int f)
{
	static const char *glyph[7] = { "   ###", "  #   ", "  #   ", "######", "  #   ", "  #   ", "###   " };
	int cx = cv->w / 2, cy = cv->h / 2 - 2;
	float R = cv->h * 0.33f;
	if (R > cv->w / 4.0f)
		R = cv->w / 4.0f;
	int tri = f % 20 < 10 ? f % 10 : 10 - f % 10;
	float r = R * (1 + 0.05f * tri / 10);

	for (int y = cy - r - 1; y <= cy + r + 1; y++)
		for (int x = cx - 2 * r - 2; x <= cx + 2 * r + 2; x++) {
			float dx = (x - cx) / 2.0f, dy = y - cy;
			int circle = dx * dx + dy * dy <= r * r;
			int corner = dx >= 0 && dy >= 0 && dx <= r && dy <= r;
			if (!circle && !corner)
				continue;

			int bg = ((x / 2 + y + f) % 14) < 2 ? 33 : 25;
			float fc = (dx / r + 0.55f) * 6 / 1.1f, fr = (dy / r + 0.75f) * 7 / 1.5f;
			if (fc >= 0 && fr >= 0 && fc < 6 && fr < 7 && glyph[(int)fr][(int)fc] == '#')
				bg = 231;
			canvas_fill(cv, x, y, 1, 1, bg);
		}

	static const char *quip;
	if (f == 0)
		quip = ONE_OF("where minish was written", "dnf install minish (coming never)");
	canvas_center(cv, cx, cy + R * 1.05f + 2, "brewed on Fedora Workstation 44", 255, -1);
	canvas_center(cv, cx, cy + R * 1.05f + 3, quip, 245, -1);
}

static void pipes(void) { play(draw_pipe, 0); }
static void zombies(void) { play(draw_zombie, 0); }
static void tux(void) { play(draw_tux, 0); }
static void matrix(void) { play(draw_matrix, 0); }
static void warp(void) { play(draw_warp, 0); }
static void fire(void) { play(draw_fire, 1); }
static void logo(void) { play(draw_logo, 0); }
static void fedora(void) { play(draw_fedora, 0); }

#pragma endregion

static const struct art arts[] = {
	{ "nyan", nyan },
	{ "fork", forkbomb },
	{ "pipe", pipes },
	{ "zombie", zombies },
	{ "tux", tux },
	{ "matrix", matrix },
	{ "warp", warp },
	{ "fire", fire },
	{ "logo", logo },
	{ "fedora", fedora },
};
#define NARTS (sizeof(arts) / sizeof(arts[0]))

const struct art *art_find(const char *name)
{
	for (size_t i = 0; i < NARTS; i++)
		if (strcmp(name, arts[i].name) == 0)
			return &arts[i];
	return NULL;
}

const struct art *art_random(void)
{
	static int seeded;
	if (!seeded) {
		srand(time(NULL) ^ getpid());
		seeded = 1;
	}
	return &arts[rand() % NARTS];
}

const char *art_names(void)
{
	static char names[128];
	if (!names[0])
		for (size_t i = 0; i < NARTS; i++) {
			if (i)
				strcat(names, "|");
			strcat(names, arts[i].name);
		}
	return names;
}
